import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class ContractTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void linearCircularAndGrowth(){Object f=TaskBinding.queue(0,2),c=TaskBinding.queue(1,2),d=TaskBinding.queue(2,2);for(Object q:new Object[]{f,c,d}){TaskBinding.put(q,'A');TaskBinding.put(q,'B');assertEquals('A',TaskBinding.get(q));}assertEquals("Очередь переполнена\n",capture(()->TaskBinding.put(f,'C')));assertEquals('B',TaskBinding.get(f));assertEquals("",capture(()->{TaskBinding.put(c,'C');assertEquals('B',TaskBinding.get(c));assertEquals('C',TaskBinding.get(c));TaskBinding.put(d,'C');TaskBinding.put(d,'D');assertEquals('B',TaskBinding.get(d));assertEquals('C',TaskBinding.get(d));assertEquals('D',TaskBinding.get(d));}));}@Test void allPairsSameObjectsFifoAndZero(){for(int a=0;a<3;a++)for(int b=0;b<3;b++){Object source=TaskBinding.queue(a,3),dest=TaskBinding.queue(b,3);Object oldSource=source,oldDest=dest;assertEquals("",capture(()->{TaskBinding.put(source,'A');TaskBinding.put(source,'B');TaskBinding.put(source,'C');TaskBinding.transfer(source,dest,3);assertEquals('A',TaskBinding.get(dest));assertEquals('B',TaskBinding.get(dest));assertEquals('C',TaskBinding.get(dest));}));assertSame(oldSource,source);assertSame(oldDest,dest);assertEquals("Очередь пуста\n",capture(()->assertEquals('\0',TaskBinding.get(source))));Object s=TaskBinding.queue(a,1),d=TaskBinding.queue(b,1);assertEquals("",capture(()->TaskBinding.transfer(s,d,0)));assertEquals("Очередь пуста\n",capture(()->assertEquals('\0',TaskBinding.get(s))));assertEquals("Очередь пуста\n",capture(()->assertEquals('\0',TaskBinding.get(d))));}} @Test void linearDestinationRemainingPositions(){Object s=TaskBinding.queue(1,2),d=TaskBinding.queue(0,3);TaskBinding.put(d,'Z');assertEquals('Z',TaskBinding.get(d));TaskBinding.put(s,'X');TaskBinding.put(s,'Y');assertEquals("",capture(()->TaskBinding.transfer(s,d,2)));assertEquals('X',TaskBinding.get(d));assertEquals('Y',TaskBinding.get(d));}}
